        ).hexdigest(),
    },
    "klean_py_sha256": {
        "expected": generator_manifest["klean_py_sha256"],
        "actual": hashlib.sha256(
            Path("/reference/tools/klean.py").read_bytes()
        ).hexdigest(),
    },
    "obligation_map_sha256": {
        "expected": generator_manifest["obligation_map_sha256"],
        "actual": hashlib.sha256(
